mapper.select:
select idfactura, idusuario, idcliente, idpuntoventa, idmetodopagosin, numerofactura, cuf, cufd, total, descuento, efectivo, cambio, fechaemision, codigo, estado, leyenda
from facturacion.facturas
where concat(numerofactura) ilike '%'||#{termino}||'%' and idusuario=#{idusuario}
order by fechaemision desc
limit #{cantidad} offset #{pagina}

select count(idfactura)
from facturacion.facturas
where concat(numerofactura) ilike '%'||#{termino}||'%' and idusuario=#{idusuario}

select idfactura, idusuario, idcliente, idpuntoventa, idmetodopagosin, total, numerofactura, cuf, cufd, descuento, efectivo, cambio, fechaemision, codigo, estado, leyenda, idpedido
from facturacion.facturas
where idfactura=#{id}

select idfactura, idusuario, idcliente, numerofactura, fechaemision, total, descuento, efectivo, cambio, idpedido
from facturacion.facturas
where date(fechaemision)=date(#{fecha}) and idusuario=#{idusuario}
order by numerofactura;
